import pandas as pd, numpy as np
s = pd.read_csv('reference/feature_sample.csv')
o = pd.read_csv('data/orders.csv.gz', dtype={'order_id':str,'line_id':str}, low_memory=False)
o['sku']=o['sku'].astype(str); o['placed_at']=pd.to_datetime(o['placed_at'])
lo=pd.Timestamp('2009-12-01'); hi=pd.Timestamp('2010-11-30')+pd.Timedelta(days=1)-pd.Timedelta(seconds=1)
fit = o[(o['placed_at']>=lo)&(o['placed_at']<=hi)]
pairs = s[['line_id','f_sku_velocity']].drop_duplicates('line_id')
sam = pairs.merge(o[['line_id','sku']], on='line_id')
tgt = dict(zip(sam['sku'], sam['f_sku_velocity']))
skus=list(tgt.keys())
V=np.array([tgt[k] for k in skus])
def score(M):
    M=np.round(np.array(M,dtype=float),6)
    return int((M==V).sum())
dailies={}
for sku in skus:
    sv=fit[fit['sku']==sku]
    dailies[sku] = sv.groupby(sv['placed_at'].dt.normalize())['units'].sum().sort_index()
# variant: EWMA adjust=True weekly trade-only
for freq in ['W-SUN','W-MON']:
    W=[]
    for sku in skus:
        wk=dailies[sku].groupby(dailies[sku].index.to_period(freq)).sum()
        W.append(wk.values.astype(float)/7)
    for a in np.arange(0.0005,1,0.0005):
        M=[]
        for x in W:
            n=len(x); w=(1-a)**np.arange(n-1,-1,-1,dtype=float)
            M.append((x*w).sum()/w.sum())
        sc=score(M)
