import pandas as pd, numpy as np
s = pd.read_csv('reference/feature_sample.csv')
o = pd.read_csv('data/orders.csv.gz', dtype={'order_id':str,'line_id':str}, low_memory=False)
o['sku']=o['sku'].astype(str); o['placed_at']=pd.to_datetime(o['placed_at'])
lo=pd.Timestamp('2009-12-01'); hi=pd.Timestamp('2010-11-30')+pd.Timedelta(days=1)-pd.Timedelta(seconds=1)
fit = o[(o['placed_at']>=lo)&(o['placed_at']<=hi)]
pairs = s[['line_id','f_sku_velocity']].drop_duplicates('line_id')
sam = pairs.merge(o[['line_id','sku']], on='line_id')
tgt = dict(zip(sam['sku'], sam['f_sku_velocity']))
skus=list(tgt.keys())
V=np.array([tgt[k] for k in skus])
daily = fit.groupby(['sku', fit['placed_at'].dt.normalize()])['units'].sum().unstack('sku').sort_index()
idxF = pd.date_range('2009-12-01','2010-11-30',freq='D')
D = daily.reindex(idxF, fill_value=0.0)[skus].values.astype(float)  # (365,419)
T,N=D.shape
def ewm_finals(X, a, adj):
    # X (T,N); return final ewm for each column
    if adj:
        p=(1-a)**np.arange(T-1,-1,-1,dtype=float)
        return (X*p).sum(axis=0)/p.sum()
    else:
        p=a*(1-a)**np.arange(T-1,-1,-1,dtype=float)
        return (X*p).sum(axis=0)
def score(M):
    return int((np.abs(np.round(M,6)-np.round(V,6))<1e-9).sum())
found=[]
for w in [1,2,3,4,5,6,7,10,14,21,28,30,60,90]:
    if w==1: X=D
    else:
        X=pd.DataFrame(D).rolling(w).mean().values
        # leading NaNs -> treat as 0? try both fillna(0)
        X=np.nan_to_num(X)
    for adj in [False,True]:
        for sp in range(2,367):
            a=2.0/(sp+1)
            sc=score(ewm_finals(X,a,adj))
            if sc>2: found.append((sc,w,adj,sp))
        # alpha grid
        for a in [0.05,0.1,0.15,0.2,0.25,0.3,0.35,0.4,0.5,0.6,0.7,0.8,0.9]:
            sc=score(ewm_finals(X,a,adj))
            if sc>2: found.append((sc,w,adj,('a',a)))
print(found[:20])
EOF"}

