    for sku in skus:
        d=dailies[sku]
        st={'fit':pd.Timestamp('2009-12-01'),'first':d.index[0],'listed':fl.get(sku,d.index[0])}[start]
        en={'fit':pd.Timestamp('2010-11-30'),'last':d.index[-1]}[end]
        idx=pd.date_range(st,en,freq='D')
        out.append(d.reindex(idx,fill_value=0.0).values.astype(float))
