def solve(x, t):
    # returns dict of (adj)->alpha if solvable
    res={}
    for adj in (True,False):
        f=lambda a: float(pd.Series(x).ewm(alpha=a,adjust=adj).mean().iloc[-1])
        lo_,hi_=1e-9,1-1e-9
